var body = $input.first().json;
var msg = body["message"] || body["edited_message"];
if (!msg) return [{json:{skip:true}}];
var chat = msg["chat"] || {};
var from = msg["from"] || {};
var senderId = "" + chat["id"];
var senderName = from["first_name"] || "Patient";
var messageText = (msg["text"] || "").trim();
var normalizedText = messageText.toLowerCase();
return [{json:{senderId:senderId,senderName:senderName,messageText:messageText,normalizedText:normalizedText,platform:"telegram"}}];

var allItems = $input.all();
var msg = null;
var sessionRow = null;
for (var i = 0; i < allItems.length; i++) {
  var item = allItems[i].json;
  if (item["senderId"]) { msg = item; }
  if (item["sender_id"]) { sessionRow = item; }
}
if (!msg) { return [{json:{skip:true}}]; }

var state = "new";
var tempSlots = "";
var reason = "";
var selectedSlot = "";
var selectedDatetime = "";
var patientName = msg["senderName"] || "Patient";

if (sessionRow) {
  state = sessionRow["state"] || "new";
  tempSlots = sessionRow["temp_slots"] || "";
  reason = sessionRow["reason"] || "";
  selectedSlot = sessionRow["selected_slot"] || "";
  selectedDatetime = sessionRow["selected_datetime"] || "";
  patientName = sessionRow["patient_name"] || patientName;
}

if (!selectedSlot && tempSlots) {
  try {
    var tsParsed = JSON.parse(tempSlots);
    if (tsParsed && tsParsed["selected"]) {
      selectedSlot = tsParsed["selected"];
      if (!selectedDatetime && tsParsed["selectedDatetime"]) {
        selectedDatetime = tsParsed["selectedDatetime"];
      }
    }
  } catch(e) {}
}

var resetWords = ["start","restart","cancel","reset"];
for (var j = 0; j < resetWords.length; j++) {
  if (msg["normalizedText"] && msg["normalizedText"].indexOf(resetWords[j]) >= 0) {
    state = "new";
    break;
  }
}

var result = {};
result["senderId"] = msg["senderId"];
result["senderName"] = msg["senderName"];
result["messageText"] = msg["messageText"];
result["normalizedText"] = msg["normalizedText"];
result["platform"] = msg["platform"];
result["state"] = state;
result["tempSlots"] = tempSlots;
result["reason"] = reason;
result["selectedSlot"] = selectedSlot;
result["selectedDatetime"] = selectedDatetime;
result["patientName"] = patientName;
return [{json:result}];

var d = $input.first().json;
var result = {};
for (var k in d) { result[k] = d[k]; }
result["replyText"] = "မင်္ဂလာပါ! ClinicAI Myanmar\n\nAppointment ယူဖို့ ကူညီပေးပါမယ်\n\nဆရာဝန်ဆီ လာရတဲ့ ကြောင်းကို ပြောပါ\n(ဥပမာ: ချမ်းတက်, ဆေးစစ်, မျက်စိနာ)";
result["newState"] = "awaiting_reason";
return [{json:result}];

var d = $input.first().json;
var reason = d["messageText"];

var today = new Date();
var tmr = new Date(today); tmr.setDate(today.getDate()+1);
var d2 = new Date(today); d2.setDate(today.getDate()+2);
function fmt(x) { return (x.getDate()) + "/" + (x.getMonth()+1); }

var tmrDate = tmr.toISOString().split("T")[0];
var d2Date = d2.toISOString().split("T")[0];

var slots = [
  {key:"1",label:"မနက်ဖြန် "+fmt(tmr)+" 9:00 AM",datetime:tmrDate+"T09:00:00"},
  {key:"2",label:"မနက်ဖြန် "+fmt(tmr)+" 11:00 AM",datetime:tmrDate+"T11:00:00"},
  {key:"3",label:"မနက်ဖြန် "+fmt(tmr)+" 3:00 PM",datetime:tmrDate+"T15:00:00"},
  {key:"4",label:fmt(d2)+" 9:00 AM",datetime:d2Date+"T09:00:00"},
  {key:"5",label:fmt(d2)+" 2:00 PM",datetime:d2Date+"T14:00:00"}
];

var slotLines = [];
for (var i = 0; i < slots.length; i++) {
  slotLines.push(slots[i]["key"] + ". " + slots[i]["label"]);
}
var slotText = slotLines.join("\n");

var result = {};
for (var k in d) { result[k] = d[k]; }
result["reason"] = reason;
result["tempSlots"] = JSON.stringify(slots);
result["replyText"] = "OK! \"" + reason + "\" အတွက် slot ရွေးပါ:\n\n" + slotText + "\n\nနံပါတ် (1-5) ပို့ပါ";
result["newState"] = "awaiting_slot";
return [{json:result}];

var d = $input.first().json;
var input = (d["messageText"] || "").trim();
var slots = [];
try {
  var parsed = JSON.parse(d["tempSlots"] || "[]");
  slots = parsed["slots"] || parsed;
} catch(e) {}

var chosen = null;
for (var i = 0; i < slots.length; i++) {
  if (input === slots[i]["key"] || input.indexOf(slots[i]["key"]) === 0) {
    chosen = slots[i];
    break;
  }
}

var result = {};
for (var k in d) { result[k] = d[k]; }

if (!chosen) {
  result["replyText"] = "နံပါတ် 1 မှ " + slots.length + " ရွေးပါ\n(ဥပမာ 1 ဆိုပြီး ပို့ပါ)";
  result["newState"] = "awaiting_slot";
  return [{json:result}];
}

result["selectedSlot"] = chosen["label"];
result["selectedDatetime"] = chosen["datetime"];
result["tempSlots"] = JSON.stringify({slots:slots,selected:chosen["label"],selectedDatetime:chosen["datetime"]});
result["replyText"] = chosen["label"] + " ရွေးပါပြီ OK\n\nနောက်ဆုံး — မင်းနာမည် ပြောပြပါ";
result["newState"] = "awaiting_name";
return [{json:result}];

var d = $input.first().json;
var patientName = (d["messageText"] || "").trim();

var result = {};
for (var k in d) { result[k] = d[k]; }
result["patientName"] = patientName;
result["replyText"] = "Appointment Confirm ပါပြီ!\n\nPatient: " + patientName + "\nSlot: " + d["selectedSlot"] + "\nကြောင်းရင်း: " + d["reason"] + "\n\nReminder 1 နာရီ အလိုမှာ ပို့ပေးပါမယ်\n\nမေးစရာရှိရင် ဒီ bot ကို message ပို့ပါ";
result["newState"] = "confirmed";
result["saveBooking"] = true;
return [{json:result}];
